package com.ailab.system.report.provider;
import com.ailab.system.report.config.*; import com.ailab.system.report.model.*; import java.util.*; import org.springframework.stereotype.Component;
@Component public final class IprSummaryProvider extends AbstractLabDataSourceProvider { public IprSummaryProvider(){super(ReportConfigCatalog.IPR_SUMMARY,new LinkedHashSet<String>(Arrays.asList("id","iprNo","iprName","iprType","iprStage","ownerId","plannedSubmitDate","actualSubmitDate")));} @Override protected boolean supports(ReportPeriod.Kind kind){return true;} protected ReportSectionData loadValidated(ReportQueryCriteria c,ReportSectionConfig s){List<Map<String,Object>>r=copyRows(mapper().selectIprs(c));return section(c,s,r,summaryCount(r));}}
